/*
Head over to frag.glsl for all the ray marching fun
*/
let theShader, sha;
let z = 0;
let ssao = true;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2628886/files/vert.glsl', 'frag.glsl');
}

function setup() {
  // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);
  let cnv = createCanvas(windowHeight*4/3, windowHeight, WEBGL);
	cnv.position(140,0);
	sha = createFramebuffer();
}

function draw() {
	z += 0.01;
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))){
		ssao = false;
	} else {
		ssao = true;
	}
  // shader() sets the active shader with our shader
	sha.begin();
	clear();
  // setUniform() sends values to the shader
  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	theShader.setUniform("u_z", z);
	theShader.setUniform("u_ssao", ssao);
	shader(theShader);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
	sha.end();

	image(sha, -width/2, -height/2);
}


// === Tab: vert.glsl ===
precision mediump float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}

// === Tab: frag.glsl ===
precision mediump float;

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;
uniform float u_z;
uniform bool u_ssao;

#define MAX_STEPS 25
#define MAX_DIST 20.
#define SURF_DIST .01

// SDFs and operations from Inigo Quilez:
// https://iquilezles.org/articles/distfunctions/

float sdSphere(vec4 s, vec3 p){
	return length(p - s.xyz) - s.w;
}

float sdPlane(vec3 p){
	// Assumes you want a plane with normal vec3(0, 1, 0) at y=0;
	return p.y;
}

float opSmoothUnion( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

// Much of the content below is informed by these tutorials + my comments and some modifications:
// https://www.youtube.com/watch?v=PGtv-dBi2wE&list=PLGmrMu-IwbgtMxMiV3x4IrHPlPmg7FD-P&index=2
// https://www.youtube.com/watch?v=2YZClgDWCaM
// https://www.youtube.com/watch?v=6zYTrFRVGiU

// Gets the distance to all objects in the scene, essentially where we set up the scene for now
float GetDist(vec3 p){
	// x, y, z, r of the spheres
	vec4 s0 = vec4(0.3*cos(0.3*u_z), 1.7 + sin(0.8*u_z), 6, 1);
	// Distance to the spheres
	float s0Dist = sdSphere(s0, p);
	// Distance to the ground plane
	float planeDist = sdPlane(p);

	// Shortest distance
	float d = opSmoothUnion(s0Dist, planeDist, 0.6); //min(sphereDist, planeDist);
	return d;
}

// March the ray!
float RayMarch(vec3 ro, vec3 rd){
	float dO = 0.;

	for (int i=0; i<MAX_STEPS; i++){
		// Ray origin + ray direction * distance from the origin
		vec3 p = ro + rd*dO;
		// Get the distance to the scene
		float dS = GetDist(p);
		dO += dS;
		// Either past the max distance or collided with a surface
		if (dO>MAX_DIST || dS<SURF_DIST) break;
	}
	return dO;
}

// Used to get soft shadows
float RayMarchSoft(vec3 ro, vec3 rd){
	float dO = 0.2;

	float res = 1.0;
	for (int i=0; i<MAX_STEPS; i++){
		// Ray origin + ray direction * distance from the origin
		vec3 p = ro + rd*dO;
		// Get the distance to the scene
		float dS = GetDist(p);
		if (dS < 0.01) return 0.0;
		dO += dS;
		// This value is the main thing that tracks the proximity to a surface and allows us to get the softness
		res = min(res, 6.0 * dS/dO);
		if (dO>MAX_DIST) break;
	}
	return res;
}

// Get normal by testing another point very close and getting the slope
vec3 GetNormal(vec3 p){
	float d = GetDist(p);
	vec2 e = vec2(.01, 0);
	// e.xyy == vec3(.01, 0, 0), etc. Just a faster way to write by swizzling
	vec3 n = d - vec3(GetDist(p-e.xyy),
										GetDist(p-e.yxy),
										GetDist(p-e.yyx));

	return normalize(n);
}

// Ambient occlusion
float ao(vec3 p, vec3 n){
	float e = 0.02;
	float res = 0.0;
	// Starting weight for the arithmetic series (1/2 + 1/4 + 1/8 + ...)
	float weight = 0.5;

	// Increasing or decreasing the iteration count affects resolution
	for (int i = 0; i < 8; ++i){
		float d = e * float(i);
		// Weight is used to give priority to terms earlier in the sequence
		res += weight * (1. - (d - GetDist(p + d*n)));
		weight *= 0.5;
	}

	return res;
}

float GetLight(vec3 p, bool soft_shadow){
	vec3 lightPos = vec3(2, 4, 4);
	// Move the light around
	//lightPos.xz += vec2(sin(0.5*u_z), cos(0.5*u_z))*3.;
	// Normalized direction vector between the light and the surface point
	vec3 l = normalize(lightPos - p);
	// Normal vector of the surface point
	vec3 n = GetNormal(p);

	float dif = clamp(dot(n, l), 0.0, 1.);
	// Hard shadow calculation
	// Ray march from point p in the direction of the light, need to increase the distance slightly otherwise almost everything appears to be in shadow
	float d = 0.0;
	if (soft_shadow){
		float d = RayMarchSoft(p+n*SURF_DIST, l);
		dif *= d;
		float indirectLight = (1. - ao(p, n));
		dif += indirectLight;
	} else {
		d = RayMarch(p+n*SURF_DIST*1.5, l);
		if (d < length(lightPos-p)) dif *= .1;
	}

	return dif;
}

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5*u_resolution.xy)/u_resolution.y;
	uv.y = -uv.y;

	vec3 col = vec3(0);

	// Ray origin
	vec3 ro = vec3(0, 1.5, -2);
	// Ray direction
	vec3 rd = normalize(vec3(uv.x, uv.y, 1));

	float d = RayMarch(ro, rd);

	vec3 p = ro + rd*d;

	// Diffuse lighting
	float dif = GetLight(p, u_ssao);
	// Modify contrast
	float s_c = 0.3;
	float boost = 0.15;
	if (dif < s_c){
		dif += boost*(s_c-dif);
	}

	// Distance is greater than 1 so we need to scale it to see anything, put this into col if you want to show a depth map rather than lighting
	//d /= 8.;
	//d = pow(d, 2.);

	col = vec3(dif);
  gl_FragColor = vec4(col, 1.0);
}

